/**
 * Client.js
 *
 * A paying household. One client record can own several animals and is the
 * thing invoices are raised against.
 */

module.exports = {

  attributes: {

    displayName: {
      type: 'string',
      required: true,
      maxLength: 160,
      description: 'How the household is addressed on paperwork, e.g. "Mr & Mrs Halloran".'
    },

    billingEmail: {
      type: 'string',
      required: true,
      isEmail: true,
      maxLength: 200
    },

    billingPostcode: {
      type: 'string',
      allowNull: true,
      maxLength: 12
    },

    balanceOwedPence: {
      type: 'number',
      defaultsTo: 0,
      description: 'Outstanding balance across every unpaid invoice, in pence.'
    },

    isOnPaymentPlan: {
      type: 'boolean',
      defaultsTo: false
    },

    registeredAt: {
      type: 'number',
      defaultsTo: 0
    },

    clinic: {
      model: 'clinic',
      required: true
    },

    patients: {
      collection: 'patient',
      via: 'client'
    },

    invoices: {
      collection: 'invoice',
      via: 'client'
    }

  }

};

