/**
 * User.js
 *
 * Everybody who can sign in. Practice staff get one of the clinical or admin
 * roles; pet owners who use the client portal get `role: 'client'` and a
 * `client` association pointing at the billing record their animals hang off.
 *
 * @docs https://sailsjs.com/docs/concepts/models-and-orm/models
 */

module.exports = {

  attributes: {

    emailAddress: {
      type: 'string',
      required: true,
      unique: true,
      isEmail: true,
      maxLength: 200,
      example: 'sam.okafor@northgatevets.co.uk'
    },

    password: {
      type: 'string',
      required: true,
      description: 'Securely hashed representation of the user\'s login password.',
      protect: true,
      example: '2$28a8eabna301089103-13948134nad'
    },

    fullName: {
      type: 'string',
      required: true,
      maxLength: 120
    },

    jobTitle: {
      type: 'string',
      allowNull: true,
      maxLength: 120,
      description: 'Free text shown in the staff directory, e.g. "Senior Surgeon".'
    },

    role: {
      type: 'string',
      isIn: ['client', 'receptionist', 'nurse', 'veterinarian', 'practice_manager', 'admin'],
      defaultsTo: 'client'
    },

    phone: {
      type: 'string',
      allowNull: true,
      maxLength: 40
    },

    marketingOptIn: {
      type: 'boolean',
      defaultsTo: false
    },

    appointmentRemindersOptIn: {
      type: 'boolean',
      defaultsTo: true
    },

    preferredContactMethod: {
      type: 'string',
      isIn: ['email', 'sms', 'phone'],
      defaultsTo: 'email'
    },

    passwordResetToken: {
      type: 'string',
      allowNull: true,
      protect: true
    },

    passwordResetTokenExpiresAt: {
      type: 'number',
      defaultsTo: 0
    },

    twoFactorSecret: {
      type: 'string',
      allowNull: true,
      protect: true,
      description: 'Base32 TOTP seed. Only set for staff accounts.'
    },

    isAccountLocked: {
      type: 'boolean',
      defaultsTo: false
    },

    lastSeenAt: {
      type: 'number',
      defaultsTo: 0
    },

    //  ╔═╗╔═╗╔═╗╔═╗╔═╗╦╔═╗╔╦╗╦╔═╗╔╗╔╔═╗
    //  ╠═╣╚═╗╚═╗║ ║║  ║╠═╣ ║ ║║ ║║║║╚═╗
    //  ╩ ╩╚═╝╚═╝╚═╝╚═╝╩╩ ╩ ╩ ╩╚═╝╝╚╝╚═╝

    clinic: {
      model: 'clinic',
      description: 'The site this user is based at. Staff only ever work at one site.'
    },

    client: {
      model: 'client',
      description: 'Only set for portal users -- the billing record they can see.'
    }

  },

  customToJSON: function () {
    // Never let credential material leave the building, whichever endpoint is
    // serialising the record.
    return _.omit(this, ['password', 'passwordResetToken', 'twoFactorSecret']);
  }

};

extraFiles.api/policies/is-clinic-staff.js:
/**
 * is-clinic-staff.js
 *
 * Keeps portal users (pet owners) out of the internal screens. Assumes
 * `isLoggedIn` has already run and populated `req.me`.
 */

var STAFF_ROLES = ['receptionist', 'nurse', 'veterinarian', 'practice_manager', 'admin'];

module.exports = function (req, res, proceed) {

  if (!req.me) {
    return res.unauthorized();
  }

  if (!_.includes(STAFF_ROLES, req.me.role)) {
    return res.forbidden('This area is for practice staff only.');
  }

  return proceed();

};

extraFiles.api/policies/is-logged-in.js:
/**
 * is-logged-in.js
 *
 * Turns the signed-in user's id in the session into a full record on `req.me`
 * so that actions and downstream policies do not each have to look it up.
 *
 * @docs https://sailsjs.com/docs/concepts/policies
 */

module.exports = async function (req, res, proceed) {

  if (!req.session.userId) {
    return res.unauthorized();
  }

  var loggedInUser = await User.findOne({ id: req.session.userId }).populate('clinic');

  if (!loggedInUser) {
    // Session points at a user who has since been deleted. Bin the session
    // rather than leaving the browser in a half-signed-in state.
    delete req.session.userId;
    return res.unauthorized();
  }

  if (loggedInUser.isAccountLocked) {
    return res.forbidden('Your account has been locked. Please speak to the practice manager.');
  }

  req.me = loggedInUser;

  // Cheap presence tracking for the "who is on the system" widget.
  if (Date.now() - loggedInUser.lastSeenAt > 60 * 1000) {
    await User.updateOne({ id: loggedInUser.id }).set({ lastSeenAt: Date.now() });
  }

  return proceed();

};

